const https = require("https");
const fs = require("fs");

function get(url) {
  return new Promise((resolve, reject) => {
    https.get(url, { headers: { "user-agent": "terrypanel" } }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        res.resume();
        return get(res.headers.location).then(resolve, reject);
      }
      const chunks = [];
      res.on("data", (c) => chunks.push(c));
      res.on("end", () => resolve({ status: res.statusCode, body: Buffer.concat(chunks) }));
    }).on("error", reject);
  });
}

(async () => {
  const builds = JSON.parse((await get("https://api.papermc.io/v2/projects/velocity")).body.toString("utf8"));
  const versions = builds.versions.filter((v) => !v.includes("SNAPSHOT"));
  const version = "{{PROXY_VERSION}}" !== "latest" ? "{{PROXY_VERSION}}" : versions[versions.length - 1];
  const buildList = JSON.parse((await get(`https://api.papermc.io/v2/projects/velocity/versions/${version}/builds`)).body.toString("utf8")).builds;
  const build = buildList[buildList.length - 1].build;
  console.log(`Downloading Velocity ${version} build ${build}`);
  const jar = await get(`https://api.papermc.io/v2/projects/velocity/versions/${version}/builds/${build}/downloads/velocity-${version}-${build}.jar`);
  if (jar.status !== 200) throw new Error(`Velocity download returned ${jar.status}`);
  fs.writeFileSync("velocity.jar", jar.body);
  console.log(`Saved velocity.jar (${(jar.body.length / 1024 / 1024).toFixed(1)} MB)`);
})().catch((err) => {
  console.error(err.message);
  process.exit(1);
});
